    aIngress = 0xBD63FC461508FBF7ULL;
    aCarry = 0x9CC8C84B2AF34E65ULL;
    aWandererA = 0xB5034BAE2F7997AFULL;
    aWandererB = 0xB0CD9F697AD578B4ULL;
    aWandererC = 0xFEE226F1A9AA7A64ULL;
